def handle_events(mode, events, store, settings):
    if mode == "preview":
        return preview_unique(events)
    if mode != "commit":
        raise ValueError("unknown mode")
    return process_batch(events, store, settings)

def process_batch(events, store, settings):
    accepted = []
    for event in events:
        tenant = event.get("tenant")
        if settings["tenant_required"] and not tenant:
            raise ValueError("tenant required")
        if settings["deduplicate"]:
            if not reserve_once(store, tenant, event["id"]):
                continue
        accepted.append(event)
    return accepted

